    {
        

        companion object
    }
    
    data class PushBack(
        val `value`: im.g.gimcore.ChatSummary) : ChatListDiff()
        
    {
        

        companion object
    }
    
    object PopFront : ChatListDiff()
    
    
    object PopBack : ChatListDiff()
    
    
