public object FfiConverterTypeChatListDiff : FfiConverterRustBuffer<ChatListDiff>{
    override fun read(buf: ByteBuffer): ChatListDiff {
        return when(buf.getInt()) {
            1 -> ChatListDiff.Append(
                FfiConverterSequenceTypeChatSummary.read(buf),
                )
            2 -> ChatListDiff.Clear
            3 -> ChatListDiff.PushFront(
                FfiConverterTypeChatSummary.read(buf),
                )
            4 -> ChatListDiff.PushBack(
                FfiConverterTypeChatSummary.read(buf),
                )
            5 -> ChatListDiff.PopFront
            6 -> ChatListDiff.PopBack
            7 -> ChatListDiff.Insert(
                FfiConverterUInt.read(buf),
                FfiConverterTypeChatSummary.read(buf),
                )
            8 -> ChatListDiff.Set(
                FfiConverterUInt.read(buf),
                FfiConverterTypeChatSummary.read(buf),
                )
            9 -> ChatListDiff.Remove(
                FfiConverterUInt.read(buf),
                )
            10 -> ChatListDiff.Truncate(
                FfiConverterUInt.read(buf),
                )
