            is ChatListDiff.PushFront -> {
                buf.putInt(3)
                FfiConverterTypeChatSummary.write(value.`value`, buf)
                Unit
            }
            is ChatListDiff.PushBack -> {
                buf.putInt(4)
                FfiConverterTypeChatSummary.write(value.`value`, buf)
                Unit
